#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/init.h>
#include <zephyr/ztest.h>

#include "device_api.h"

/*
 * Used to test initialization ordering. The init functions for the
 * devices defined below will add a pointer to themselves to the
 * init_record array. The test will then verify that the pointers are
 * in the expected order.
 */
static const void *init_record[16];
static size_t init_record_idx;

static void init_record_add(const void *dev)
{
	if (init_record_idx < ARRAY_SIZE(init_record)) {
		init_record[init_record_idx++] = dev;
	}
}

static int init_fn(const struct device *dev)
{
	init_record_add(dev);
	return 0;
}

/* For testing SYS_INIT at POST_KERNEL */
static int post_kernel_obj;

static int sys_init_fn(const struct device *dev)
{
	ARG_UNUSED(dev);

	init_record_add(&post_kernel_obj);
	return 0;
}

DEVICE_DEFINE(dev_pre_1_p70, "dev_pre_1_p70", init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_1, 70, NULL);
DEVICE_DEFINE(dev_pre_1_p60, "dev_pre_1_p60", init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_1, 60, NULL);
DEVICE_DEFINE(dev_pre_2_p50, "dev_pre_2_p50", init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_2, 50, NULL);
DEVICE_DEFINE(dev_pre_2_p40, "dev_pre_2_p40", init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_2, 40, NULL);
DEVICE_DEFINE(dev_post_p30, "dev_post_p30", init_fn, NULL, NULL, NULL,
	      POST_KERNEL, 30, NULL);
DEVICE_DEFINE(dev_app_p20, "dev_app_p20", init_fn, NULL, NULL, NULL,
	      APPLICATION, 20, NULL);
DEVICE_DEFINE(dev_app_p10, "dev_app_p10", init_fn, NULL, NULL, NULL,
	      APPLICATION, 10, NULL);
#ifdef CONFIG_SMP
DEVICE_DEFINE(dev_smp_p0, "dev_smp_p0", init_fn, NULL, NULL, NULL,
	      SMP, 0, NULL);
#endif

SYS_INIT(sys_init_fn, POST_KERNEL, 0);

static const void *const expected_order[] = {
	DEVICE_GET(dev_pre_1_p60),
	DEVICE_GET(dev_pre_1_p70),
	DEVICE_GET(dev_pre_2_p40),
	DEVICE_GET(dev_pre_2_p50),
	&post_kernel_obj,
	DEVICE_GET(dev_post_p30),
	DEVICE_GET(dev_app_p10),
	DEVICE_GET(dev_app_p20),
#ifdef CONFIG_SMP
	DEVICE_GET(dev_smp_p0),
#endif
};

/* For testing device de-initialization */
static bool deinit_test_device_initialized;

static int deinit_test_device_init(const struct device *dev)
{
	ARG_UNUSED(dev);
	deinit_test_device_initialized = true;
	return 0;
}

#ifdef CONFIG_DEVICE_DEINIT
static int deinit_test_device_deinit(const struct device *dev)
{
	ARG_UNUSED(dev);
	deinit_test_device_initialized = false;
	return 0;
}
#endif

DEVICE_DEFINE(deinit_test_device, "deinit_test_device",
	      deinit_test_device_init,
#ifdef CONFIG_DEVICE_DEINIT
	      deinit_test_device_deinit,
#else
	      NULL,
#endif
	      NULL, NULL, POST_KERNEL, 0, NULL);

ZTEST(device, test_deinit_not_supported)
{
	const struct device *dev = DEVICE_GET(deinit_test_device);
	int err;

	zassert_true(device_is_ready(dev), "device should be ready");

#ifdef CONFIG_DEVICE_DEINIT
	ztest_test_skip();
#endif

	err = device_deinit(dev);
	zassert_equal(err, -ENOSYS, "deinit should not be supported");
}

ZTEST(device, test_deinit_success_and_redeinit)
{
	const struct device *dev = DEVICE_GET(deinit_test_device);
	int err;

#ifndef CONFIG_DEVICE_DEINIT
	ztest_test_skip();
#endif

	zassert_true(device_is_ready(dev), "device should be ready");
	zassert_true(deinit_test_device_initialized, "device should be initialized");

	err = device_deinit(dev);
	zassert_ok(err, "deinit should succeed");
	zassert_false(device_is_ready(dev), "device should not be ready");
	zassert_false(deinit_test_device_initialized, "device should be deinitialized");

	/* Re-initialize the device */
	err = device_init(dev);
	zassert_ok(err, "re-init should succeed");
	zassert_true(device_is_ready(dev), "device should be ready again");
	zassert_true(deinit_test_device_initialized, "device should be initialized again");
}

ZTEST(device, test_device_api)
{
	const struct device *const dev_a = DEVICE_GET(dev_a);
	const struct device *const dev_b = DEVICE_GET(dev_b);
	const struct device *const dev_c = DEVICE_GET(dev_c);
	const struct device *const dev_d = DEVICE_GET(dev_d);
	const struct device *const dev_e = DEVICE_GET(dev_e);
	const struct device *const dev_f = DEVICE_GET(dev_f);

	zassert_true(device_is_ready(dev_a));
	zassert_true(device_is_ready(dev_b));
	zassert_true(device_is_ready(dev_c));
	zassert_true(device_is_ready(dev_d));
	zassert_true(device_is_ready(dev_e));
	zassert_false(device_is_ready(dev_f));
}

ZTEST(device, test_device_api_extends)
{
	const struct device *const dev_a = DEVICE_GET(dev_a);
	const struct device *const dev_b = DEVICE_GET(dev_b);

	zassert_true(device_is_ready(dev_a));
	zassert_true(device_is_ready(dev_b));

	zassert_true(is_device_api_my_api(dev_a));
	zassert_true(is_device_api_my_api(dev_b));

	zassert_false(is_device_api_my_ext_api(dev_a));
	zassert_true(is_device_api_my_ext_api(dev_b));

	const struct my_ext_api *ext_api = (const struct my_ext_api *)dev_b->api;

	zassert_equal(ext_api->my_ext_func(dev_b), 1);
}

ZTEST(device, test_device_api_extends_grandchild)
{
	const struct device *const dev_d = DEVICE_GET(dev_d);

	zassert_true(device_is_ready(dev_d));

	zassert_true(is_device_api_my_api(dev_d));
	zassert_true(is_device_api_my_ext_api(dev_d));

	const struct my_ext_api *ext_api = (const struct my_ext_api *)dev_d->api;

	zassert_equal(ext_api->my_ext_func(dev_d), 1);
}

ZTEST(device, test_device_api_extends_sibling)
{
	const struct device *const dev_c = DEVICE_GET(dev_c);
	const struct device *const dev_e = DEVICE_GET(dev_e);

	zassert_true(device_is_ready(dev_c));
	zassert_true(device_is_ready(dev_e));

	zassert_true(is_device_api_my_api(dev_c));
	zassert_true(is_device_api_my_api(dev_e));

	zassert_false(is_device_api_my_ext_api(dev_c));
	zassert_false(is_device_api_my_ext_api(dev_e));
}

ZTEST(device, test_device_init_level)
{
	bool seq_correct = true;
	size_t i;

	if (init_record_idx != ARRAY_SIZE(expected_order)) {
		TC_PRINT("Wrong number of init calls: %u, expected %u\n",
			 (unsigned int)init_record_idx,
			 (unsigned int)ARRAY_SIZE(expected_order));
		seq_correct = false;
		goto out;
	}

	for (i = 0; i < ARRAY_SIZE(expected_order); i++) {
		if (init_record[i] != expected_order[i]) {
			const struct device *rd = init_record[i];
			const struct device *ed = expected_order[i];

			TC_PRINT("Device %u/%u init order wrong\n",
				 (unsigned int)i,
				 (unsigned int)ARRAY_SIZE(expected_order));
			if (rd != NULL) {
				TC_PRINT("  Got: %s\n", rd->name);
			} else {
				TC_PRINT("  Got: NULL\n");
			}
			if (ed != NULL) {
				TC_PRINT("  Expected: %s\n", ed->name);
			} else {
				TC_PRINT("  Expected: NULL\n");
			}
			seq_correct = false;
		}
	}

out:
	zassert_true(seq_correct, "Device init sequence wrong");
}

ZTEST_SUITE(device, NULL, NULL, NULL, NULL, NULL);
